import csv,json,os
from pathlib import Path
from conceptgraph.completion.stage9 import digest,dump
R=Path(__file__).resolve().parents[1];O=R/'kitti_tracking_expanded';S=R/'statistics/kitti_expanded_full_001';report=json.loads((S/'report.json').read_text());selection=json.loads((O/'input_data/selection.json').read_text());front=json.loads((R/'mapping_evaluation/kitti_gpu_frontend_full_001/summary.json').read_text());agent=json.loads((O/'input_data/agent_manifest.json').read_text());query=json.loads((O/'graph_query_001/sequence_queries_summary.json').read_text())
rows=[]
for name,data in report['object']['methods'].items():
 c=data['counts'];m=data['metrics'];idf=report['identity']['methods'][name]['all_gated']['metrics']['IDF1'];rows.append(dict(method=name,TP=c['true_positive'],GT_observations=c['truth'],prediction_observations=c['predictions'],recall=m['recall'],matched_prediction_fraction=m['matched_prediction_fraction'],center_error_m=m['center_error_m'],duplicate_nodes=c['duplicate_nodes'],IDF1=idf['value'],IDF1_ci95_low=idf['ci95'][0],IDF1_ci95_high=idf['ci95'][1],frames=1000,sequences=10,actual_arrivals=0))
with (O/'comparison.csv').open('x') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
srows=[]
for seq,data in selection['selected'].items():
 ids=data['frame_ids'];srows.append(dict(sequence=seq,original_total_frames=data['total_frames'],first_original_frame=ids[0],last_original_frame=ids[-1],selected_frames=len(ids),RGB_frames=sum(x['sequence']==seq for x in agent['frames']),LiDAR_frames=sum(x['sequence']==seq for x in agent['frames']),nominal_dt_s=.1,measured_sensor_timestamps=False))
with (O/'sequence_selection.csv').open('x') as f:w=csv.DictWriter(f,fieldnames=list(srows[0]));w.writeheader();w.writerows(srows)
files={str(p):digest(p) for p in [S/'report.json',S/'scene_reports.json',O/'graph_query_001/sequence_queries_summary.json',R/'mapping_evaluation/kitti_gpu_frontend_full_001/summary.json',R/'mapping_evaluation/kitti_mapping_full_001/summary.json',O/'graph_query_001/frame_index.csv']}
dump(O/'completion_receipt_001.json',dict(sequences=10,frames=1000,actual_new_frontend_calls=front['actual_new_frontend_calls'],reused_gpu_smoke_frames=front['reused_frames'],mapping_methods=3,graph_query_frames=query['frames'],frame_queries=query['frame_queries'],distinct_sequence_query_units=query['independent_sequence_query_units'],navigation_arrivals=0,files_sha256=files,goal_complete=False))
lines=['# KITTI连续序列本批实验结果','', '10个连续序列，每个100帧，共1000帧。检测、SAM分割、CLIP、深度处理、三种建图比较、改进方法的对象关系图和三条固定类别查询均已实际执行。','', '|方法|匹配/官方观测|找全率|匹配预测比例|中心误差米|重复节点|IDF1|','|---|---|---|---|---|---|---|']
for r in rows:lines.append(f"|{r['method']}|{r['TP']}/{r['GT_observations']}|{r['recall']:.2%}|{r['matched_prediction_fraction']:.2%}|{r['center_error_m']:.3f}|{r['duplicate_nodes']}|{r['IDF1']:.2%}|")
lines+=['','改进方法找得更多、中心误差更小，但重复节点增多；负结果保留。官方标签有不支持类别、DontCare等，未匹配预测不全等于已确认误检，所以称“匹配预测比例”。并非官方AP/HOTA。','', '## 每帧结果怎么找','', '- 原图、LiDAR、深度、标定：`input_data/agent_inputs/<序列>/<原始帧号>/`。位姿和内参在`input_data/agent_manifest.json`。','- 检测、分割掩膜和CLIP特征：`gpu_frontend/frames/<序列>/<原始帧号>/detections.pkl.gz`；框图为`detections.jpg`。前3帧复用小试，准确路径见前端summary和frame_index.csv。','- 三种建图对象中心、尺寸、稳定ID、运动状态和深度证据：`mapping_results/frames.jsonl`，每帧一行。点云融合实际运行，但未额外复制全量累计点云，三维几何保留对象中心/尺寸和原始点云输入。','- 改进图的节点、关系边、候选与锁定：`graph_query_001/frames_graph_query.jsonl`，每帧一行。','- 仅评价使用的官方身份与查询结果：`graph_query_001/evaluation_only_query_metrics.jsonl`和`evaluation_results/`。','- 1000帧逐项入口：`graph_query_001/frame_index.csv`；序列帧区间：`sequence_selection.csv`；页面：`index.html`。','', '## 边界','', '每帧固定查询汽车、卡车、行人，共3000次帧查询，只有30个序列—固定类别查询单元，不当作3000条独立自然语言。它们用于连续图与锁定诊断，不是车辆闭环执行。KITTI没有实际到达成绩。10秒中心片段不是完整原始序列，帧间隔为名义0.1秒。与旧Object64存在2帧精确重叠。','', '更详细的区间、逐序列指标和失败统计见`evaluation_results/report.json`、`scene_reports.json`及`graph_query_001/sequence_queries_summary.json`。当前主流程无丢帧；所有开发中断和依赖错误仍保留。']
(O/'结果与逐帧目录说明.md').write_text('\n'.join(lines)+'\n')
# 浏览器页面不复制原始大图，只使用本目录入口与相对路径。
records=[]
for x in map(json.loads,(O/'graph_query_001/frames_graph_query.jsonl').open()):
 x['rgb_url']=f"input_data/agent_inputs/{x['sequence']}/{x['original_frame_id']:06d}/rgb.png";x['detection_url']=os.path.relpath(x['detection_visualization'],O);records.append(x)
(O/'viewer_records.json').write_text(json.dumps(records,ensure_ascii=False))
(O/'index.html').write_text('''<!doctype html><html lang="zh"><meta charset="utf-8"><title>KITTI连续建图结果</title><style>body{font:16px sans-serif;margin:24px;background:#f4f6f8;color:#172a3a}img{width:49%;background:#111}pre{white-space:pre-wrap;background:white;padding:16px}button,select,input{font-size:18px;margin:8px}</style><h1>KITTI连续建图与目标锁定诊断</h1><p>10序列×100帧。仅离线诊断，没有实际导航到达成绩；重复节点增多的负结果保留。</p><label>序列<select id="sequence"></select></label><label>片段内帧号<input id="frame" type="range" min="0" max="99" value="0"></label><span id="number"></span><p><img id="rgb"><img id="detection"></p><p><a href="结果与逐帧目录说明.md">结果说明</a> · <a href="comparison.csv">比较CSV</a> · <a href="graph_query_001/frame_index.csv">逐帧路径索引</a></p><pre id="detail"></pre><script>let records=[];const s=document.querySelector('#sequence'),f=document.querySelector('#frame');function show(){const r=records.find(r=>r.sequence===s.value&&r.frame_idx===+f.value);if(!r)return;document.querySelector('#number').textContent=`${r.frame_idx}/99，原始帧${r.original_frame_id}`;document.querySelector('#rgb').src=r.rgb_url;document.querySelector('#detection').src=r.detection_url;document.querySelector('#detail').textContent=JSON.stringify({节点:r.nodes,关系:r.edges,查询及锁定:r.queries,原始证据:{rgb:r.rgb,depth:r.depth,detections:r.detections}},null,2)}fetch('viewer_records.json').then(r=>r.json()).then(d=>{records=d;for(const v of [...new Set(d.map(r=>r.sequence))]){const o=document.createElement('option');o.value=v;o.textContent=v;s.append(o)}show()});s.onchange=show;f.oninput=show;</script></html>''')
print('\n'.join(lines[:10]))
